/* DO NOT EDIT THIS FILE */

#include <stdlib.h>

#define STB_IMAGE_WRITE_IMPLEMENTATION
#include <stb_image_write.h>

#include "image.h"
#include "log.h"

image_t* image_create(size_t width, size_t height) {
    image_t* image = calloc(1, sizeof(*image));
    if (image == NULL) {
        LOG_ERROR_ERRNO("calloc");
        goto fail_exit;
    }

    image->width  = width;
    image->height = height;

    image->pixels = malloc((image->width * image->height) * sizeof(*image->pixels));
    if (image->pixels == NULL) {
        LOG_ERROR_ERRNO("malloc");
        goto fail_free_image;
    }

    return image;

fail_free_image:
    free(image);
fail_exit:
    return NULL;
}

void image_destroy(image_t* image) {
    if (image->pixels != NULL) {
        free(image->pixels);
    }
    free(image);
}

int image_save_png(image_t* image, char* filename) {
    if (image == NULL || filename == NULL) {
        LOG_ERROR_NULL_PTR();
        goto fail_exit;
    }

    /* pixel_t is exactly 3 bytes (RGB), so the pixels are already laid out as tightly packed rows. */
    _Static_assert(sizeof(pixel_t) == 3, "pixel_t must be a tightly packed RGB triplet");

    if (!stbi_write_png(filename, (int)image->width, (int)image->height, 3, image->pixels,
                        (int)(image->width * sizeof(pixel_t)))) {
        LOG_ERROR("failed to write `%s`", filename);
        goto fail_exit;
    }

    return 0;

fail_exit:
    return -1;
}
